diff --git a/my_cond_branch_predictor.cc b/my_cond_branch_predictor.cc
index 9782f1c..2f6b72a 100644
--- a/my_cond_branch_predictor.cc
+++ b/my_cond_branch_predictor.cc
@@ -599,6 +599,20 @@ struct cbp_hist_t {
     tage_index_t ch_i;
     std::array<tage_tag_t, 2> ch_t;
     int perceptron_sum_at_prediction;
+    std::array<uint16_t, 12> rv_keys{};
+    std::array<uint16_t, 32> rv_visits{};
+    uint64_t rv_last = 0;
+    uint32_t rv_path = 0;
+    uint32_t rv_previous = 0;
+    std::array<uint8_t, 65> rv_recent{};
+    std::array<uint32_t, 20> rv_samples{};
+    std::array<uint32_t, 2> rv_ids{};
+    std::array<uint8_t, 2> rv_bins{};
+    uint16_t rv_generation = 0;
+    bool rv_captured = false;
+    uint64_t rv_serial = 0;
+    uint16_t rv_flag_epoch = 0;
+    bool rv_gathered = false;

     // Begin Conventional Histories
     uint64_t phist; // path history
@@ -844,6 +858,770 @@ public:
         current_hist.phist = 0;
     } // end init_histories

+    struct RvColumn {
+        uint32_t pos;
+        uint32_t neg;
+        uint16_t ratings;
+        uint8_t reg : 7;
+        uint8_t peer : 7;
+        uint8_t kind;
+        uint8_t center;
+        uint8_t shift : 4;
+        int8_t credit;
+        bool direct;
+    };
+    struct RvPanel {
+        uint16_t tag;
+        uint8_t warm : 2;
+        uint8_t yes : 5;
+        uint8_t no : 5;
+        std::array<RvColumn, 20> columns;
+    };
+    struct RvExpert {
+        uint8_t reg : 7;
+        uint8_t peer : 7;
+        uint8_t kind : 5;
+        uint8_t center;
+        uint8_t shift : 4;
+        int8_t merit;
+        bool direct;
+        std::array<uint8_t, 6> weights;
+    };
+    struct RvModel {
+        uint16_t tag;
+        uint8_t uses : 4;
+        int8_t blend : 6;
+        std::array<RvExpert, 2> experts;
+    };
+    std::array<RvPanel, 5> rv_panels{};
+    std::array<RvModel, 88> rv_models{};
+    std::array<uint64_t, 65> rv_owner{};
+    std::array<uint8_t, 65> rv_part{};
+    std::array<uint64_t, 65> rv_words{};
+    std::array<uint64_t, 4> rv_groups{};
+    std::array<uint64_t, 2> rv_live{};
+    std::array<uint8_t, 1152> rv_dense{};
+    std::array<int8_t, 128> rv_choice{};
+    std::array<int8_t, 32> rv_family{};
+    std::array<uint8_t, 65> rv_writer{};
+    uint64_t rv_decoded = 0;
+    uint64_t rv_fp_time = 0;
+    uint32_t rv_caller = 0;
+    uint32_t rv_order = 0;
+    uint32_t rv_flags = 0;
+    std::array<uint16_t, 5> rv_epoch{};
+    uint32_t rv_rng = 98362985;
+
+    unsigned rv_mix(uint32_t x) const
+    {
+        const uint32_t h = (x ^ (x >> 16)) * 0x21f0aaadu;
+        const uint32_t g = (h ^ (h >> 15)) * 0x735a2d97u;
+        return g ^ (g >> 15);
+    }
+
+    unsigned rv_rank(uint64_t x) const
+    {
+        uint64_t mag = x >> 63 ? ~x : x;
+        unsigned result = 0;
+        if (mag < 32) result = mag;
+        else {
+            unsigned shift = 0;
+            if (mag >= (1ull << 32)) { mag >>= 32; shift += 32; }
+            if (mag >= 65536) { mag >>= 16; shift += 16; }
+            if (mag >= 256) { mag >>= 8; shift += 8; }
+            if (mag >= 16) { mag >>= 4; shift += 4; }
+            if (mag >= 4) { mag >>= 2; shift += 2; }
+            if (mag >= 2) ++shift;
+            result = std::min(127u, 32 + 2 * (shift - 5) + static_cast<unsigned>((x >> (shift - 1)) & 1));
+        }
+        return x >> 63 ? 127 - result : 128 + result;
+    }
+
+    unsigned rv_float(uint64_t x, bool single) const
+    {
+        const uint32_t v = single ? static_cast<uint32_t>(x) : static_cast<uint32_t>(x >> 32);
+        const unsigned exp = single ? (v >> 23) & 255 : (v >> 20) & 2047;
+        const int rel = static_cast<int>(exp) - (single ? 127 : 1023);
+        const unsigned fraction = (v >> (single ? 21 : 18)) & 3;
+        const int magnitude = exp ? std::max(1, std::min(127, 64 + 4 * rel + static_cast<int>(fraction))) : 0;
+        return v >> 31 ? 127 - magnitude : 128 + magnitude;
+    }
+
+    unsigned rv_class(unsigned r, uint64_t x) const
+    {
+        if (!x) return 1;
